from .base import EMSSInterface


class SshManager(EMSSInterface):
    """
    EMSsim keywords related to FSM SSH service
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(SshManager, self).__init__()

    def get_fsm_ssh_status(self, enb_id=None, bts_id=None, alias=None):
        """
        Checks SSH service on FSM and returns its status.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: status of SSH service on FSM ('Enabled'/'Disabled')

        +------------+--------------------+
        |             Examples            |
        +============+====================+
        | ${status}= | get fsm ssh status |
        +------------+--------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        ssh_status = self._get_emssim().cmd_ssh_status()
        self._assert(ssh_status.run(), "Checking FSM SSH status operation failed")
        ret = ssh_status.returned_data()
        return ret['ssh_status']

    def get_ftm_ssh_status(self, enb_id=None, bts_id=None, alias=None):
        """
        Checks SSH service on FTM and returns its status.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: status of SSH service on FTM ('Enabled'/'Disabled')

        +------------+--------------------+
        |             Examples            |
        +============+====================+
        | ${status}= | get ftm ssh status |
        +------------+--------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        ssh_ftm_status = self._get_emssim().cmd_ssh_ftm_status()
        self._assert(ssh_ftm_status.run(), "Checking FTM SSH status operation failed")
        ret = ssh_ftm_status.returned_data()
        return ret['ssh_status']

    def enable_fsm_ssh(self, enb_id=None, bts_id=None, alias=None):
        """
        Enables SSH service on FSM.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------+
        |    Examples    |
        +================+
        | enable fsm ssh |
        +----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(self._get_emssim().cmd_ssh_enable().run(), "Enabling FSM SSH status operation failed")
        self._assert(self.get_fsm_ssh_status(bts_id=bts_id, alias=alias) == 'Enabled', "Wrong SSH state, should be enabled")

    def enable_ftm_ssh(self, enb_id=None, bts_id=None, alias=None):
        """
        Enables SSH service on FTM.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------+
        |    Examples    |
        +================+
        | enable ftm ssh |
        +----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(self._get_emssim().cmd_ssh_ftm_enable().run(), "Enabling FTM SSH status operation failed")
        self._assert(self.get_ftm_ssh_status(bts_id=bts_id, alias=alias) == 'Enabled', "Wrong SSH state, should be enabled")

    def disable_fsm_ssh(self, enb_id=None, bts_id=None, alias=None):
        """
        Disables SSH service on FSM.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------+
        |     Examples    |
        +=================+
        | disable fsm ssh |
        +-----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(self._get_emssim().cmd_ssh_disable().run(), "Disabling FSM SSH status operation failed")
        self._assert(self.get_fsm_ssh_status(bts_id=bts_id, alias=alias) == 'Disabled', "Wrong SSH state, should be disabled")

    def disable_ftm_ssh(self, enb_id=None, bts_id=None, alias=None):
        """
        Disables SSH service on FTM.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------+
        |     Examples    |
        +=================+
        | disable ftm ssh |
        +-----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(self._get_emssim().cmd_ssh_ftm_disable().run(), "Disabling FTM SSH status operation failed")
        self._assert(self.get_ftm_ssh_status() == 'Disabled', "Wrong SSH state, should be disabled")
